import { test, expect, vi } from "vitest";

// Mock a function
let mockFn = vi.fn();
mockFn("hello");
expect(mockFn).toHaveBeenCalledWith("hello");
expect(mockFn).toHaveBeenCalledTimes(1);

// Configure mock behavior
mockFn.mockReturnValue(42);
console.log(mockFn());  // 42

// Mock an entire module
vi.mock("./api.js", () => ({
  fetchUser: vi.fn().mockResolvedValue({ id: 1, name: "Test" })
}));

import { fetchUser } from "./api.js";
test("fetchUser returns test user", async () => {
  let user = await fetchUser(1);
  expect(user.name).toBe("Test");
});

// Spy on a method
let user = { name: "Alex", greet() { return "Hi!"; } };
let spy = vi.spyOn(user, "greet");
user.greet();
expect(spy).toHaveBeenCalled();
spy.mockRestore();  // restore original method

// Fake timers
vi.useFakeTimers();

let callback = vi.fn();
setTimeout(callback, 1000);

vi.advanceTimersByTime(1000);
expect(callback).toHaveBeenCalled();  // true!

vi.useRealTimers();

import { http, HttpResponse } from "msw";

export const handlers = [
  http.get("/api/users", () => {
    return HttpResponse.json([
      { id: 1, name: "Alex" },
      { id: 2, name: "Sam" }
    ]);
  }),

  http.get("/api/users/:id", ({ params }) => {
    return HttpResponse.json({ id: params.id, name: "User" });
  }),

  http.post("/api/users", async ({ request }) => {
    let body = await request.json();
    return HttpResponse.json({ id: 3, ...body }, { status: 201 });
  })
];
